using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor {
 [InitializeOnLoad] public static class GarrisonNameVerification {
  const string Key="GarrisonNameVerification";static double start;static int checks;static string report="";static bool awaitingRocketStop;static float rocketDeadline;
  static GarrisonNameVerification(){if(SessionState.GetBool(Key,false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;}}
  public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/DoubleValley9x.unity");SessionState.SetBool(Key,true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}
  static void Check(bool ok,string text){if(!ok)throw new Exception(text);checks++;report+="PASS "+text+"\n";}
  static void Poll(){try{if(EditorApplication.timeSinceStartup-start>120)throw new Exception("Garrison verification timeout");if(!EditorApplication.isPlaying||Time.time<1)return;var w=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(w==null||!w.Initialized)return;if(awaitingRocketStop){if(Time.time<rocketDeadline)return;Check(w.GetComponent<BattlefieldAudio>().ActiveVoicesOf(BattlefieldSound.RocketBarrage)==0,"Rocket continuous sound stops after firing ends");File.WriteAllText("garrison-name-verification.txt",checks+" checks passed\n"+report);Finish(0);return;}w.enabled=false;foreach(var b in w.GetComponents<MonoBehaviour>())if(b is BattleAIController||b is AIBasicCommander)b.enabled=false;
   var hud=UnityEngine.Object.FindObjectOfType<CampaignHUD>();var service=w.GetComponent<CityManagement>();w.setup.modes.EnterInspectionMode();
   Check(Resources.LoadAll<AudioClip>("Audio/CommandVoices").Length==0,"Generated movement speech files are removed");var audio=w.GetComponent<BattlefieldAudio>();audio.Clear();audio.PlayAt(BattlefieldSound.CommandVoice,Vector3.zero);Check(audio.ActiveVoicesOf(BattlefieldSound.CommandVoice)==0,"Movement voice playback is disabled even through the legacy sound entry point");
   audio.PlayAt(BattlefieldSound.Cannon,Vector3.zero);Check(audio.GetComponentsInChildren<AudioSource>().Any(s=>s.isPlaying&&s.clip!=null&&s.clip.name=="ArtilleryLaunch"),"Ordinary artillery launch selects the supplied launch recording");audio.Clear();var orbit=w.GetComponent<TabletopCamera>();orbit.Focus(Vector2.zero);orbit.Apply();audio.PlayAt(BattlefieldSound.Explosion,Vector3.zero);Check(audio.GetComponentsInChildren<AudioSource>().Any(s=>s.isPlaying&&s.clip!=null&&s.clip.name=="ArtilleryImpact"),"Existing artillery impact uses the supplied tail without reusing the launch recording");audio.Clear();audio.PlayAt(BattlefieldSound.Construction,Vector3.zero);Check(audio.GetComponentsInChildren<AudioSource>().Any(s=>s.isPlaying&&s.clip!=null&&s.clip.name.StartsWith("EngineerWork")),"Construction selects the supplied engineer work recording");audio.Clear();
   foreach(string owner in w.players){w.SetPlayer(owner);var city=w.points.First(p=>p.ownerId==owner&&!p.isRepairSite);hud.SelectBuilding(city);var view=hud.GetComponentsInChildren<CityPanelView>(true).Last();Check(view!=null,"City panel opens for "+owner);view.Refresh();Canvas.ForceUpdateCanvases();LayoutRebuilder.ForceRebuildLayoutImmediate(view.GetComponent<RectTransform>());
    var units=service.Snapshot(city,owner).garrison;Check(units.Length>0,"Garrison fixtures exist for "+owner);
    foreach(var unit in units){var title=view.GetComponentsInChildren<Text>(true).FirstOrDefault(t=>t.name=="驻军名称"&&t.transform.parent.name=="驻军 "+unit.unitId);Check(title!=null&&title.text.Contains(unit.DisplayDesignation)&&title.text.Contains(LevelUnitAvailability.Name(unit.combatDefinition.role))&&title.text.Contains(BattleTextFormatter.Echelon(unit.combatDefinition.echelon)),"Visible title identifies "+owner+" "+unit.unitId);Check(title.fontStyle==FontStyle.Bold&&title.GetComponent<LayoutElement>().preferredHeight>=40,"Unit title has its own reserved readable space");}
    var inspect=view.GetComponentsInChildren<Button>(true).First(b=>b.name.StartsWith("查看单位："));var selected=units.First(u=>inspect.GetComponentInChildren<Text>().text.Contains(CityPanelView.GarrisonTitle(u)));inspect.onClick.Invoke();Check(hud.SelectedUnit==selected,"Inspect action opens its matching garrison unit");
   }
   var rocket=w.units.First(u=>u.ownerId==w.currentPlayer&&u.combatDefinition.role==UnitRole.RocketArtillery);rocket.Initialize();rocket.Motor?.Stop();var battery=rocket.GetComponent<ArtilleryBattery>();battery.SetSplitCooldown(0);orbit.Focus(rocket.transform.position);orbit.Apply();audio.Clear();Check(battery.Fire(w,w.currentPlayer,rocket.transform.position+Vector3.right*2).accepted,"Real rocket barrage starts");Check(audio.ActiveVoicesOf(BattlefieldSound.RocketBarrage)==1&&audio.GetComponentsInChildren<AudioSource>().Any(s=>s.isPlaying&&s.loop&&s.clip!=null&&s.clip.name=="RocketBarrage"),"Rocket barrage starts its dedicated continuous recording");
   for(int n=0;n<10;n++)w.NotifyCombatEffect(new CombatEffectEvent(CombatEffectStage.ArtilleryLaunch,rocket.unitId,rocket.ownerId,UnitRole.RocketArtillery,true,rocket.transform.position,null,null,rocket.transform.position+Vector3.right*2));Check(audio.ActiveVoicesOf(BattlefieldSound.RocketBarrage)==1,"Repeated rocket launches refresh one loop rather than stacking recordings");battery.Tick(999);awaitingRocketStop=true;rocketDeadline=Time.time+1.1f;return;
  }catch(Exception e){Debug.LogException(e);File.WriteAllText("garrison-name-verification.txt","FAIL\n"+report+e);Finish(1);}}
  static void Finish(int code){SessionState.SetBool(Key,false);EditorApplication.update-=Poll;EditorApplication.Exit(code);}
 }
}
